import{c as r,Q as t,j as a,m as s}from"./chunks/framework.BPKcPtvA.js";const h=JSON.parse('{"title":"Security Tips","description":"","frontmatter":{},"headers":[],"relativePath":"extras/security-tips.md","filePath":"extras/security-tips.md"}'),i={name:"extras/security-tips.md"};function o(l,e,n,u,c,p){return t(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="security-tips" tabindex="-1">Security Tips <a class="header-anchor" href="#security-tips" aria-label="Permalink to &quot;Security Tips&quot;">​</a></h1><p>Most WordPress security issues aren&#39;t caused by themes or plugins — they come from how WordPress is configured. Here are some basic steps to keep your WordPress environment safe.</p><h2 id="basic-security-checklist" tabindex="-1">Basic Security Checklist <a class="header-anchor" href="#basic-security-checklist" aria-label="Permalink to &quot;Basic Security Checklist&quot;">​</a></h2><ul><li>Keep your <a href="./../general/keep-wordpress-up-to-date.html">WordPress core up to date</a></li><li>Keep all your themes and plugins up to date</li><li>Use a secure username — never use &quot;admin&quot;</li><li>Use a strong, unique password — use a tool like <a href="https://strongpasswordgenerator.com/" target="_blank" rel="noreferrer">Strong Password Generator</a></li><li>Choose a unique database name and a secure database password</li><li>Change the Authentication Unique <a href="https://api.wordpress.org/secret-key/1.1/salt/" target="_blank" rel="noreferrer">Keys and Salts</a> in <code>wp-config.php</code></li><li>Use unique database table prefixes — avoid the default <code>wp_</code></li><li>Use a proper <a href="https://codex.wordpress.org/Using_Permalinks" target="_blank" rel="noreferrer">permalink structure</a></li></ul><h2 id="hosting" tabindex="-1">Hosting <a class="header-anchor" href="#hosting" aria-label="Permalink to &quot;Hosting&quot;">​</a></h2><p>Security issues can also come from unreliable hosting providers, usually <a href="./../general/low-budget-hosts.html">cheap ones</a>. A reputable host with up-to-date server software is an important layer of security.</p><h2 id="further-reading" tabindex="-1">Further Reading <a class="header-anchor" href="#further-reading" aria-label="Permalink to &quot;Further Reading&quot;">​</a></h2><ul><li><a href="https://code.tutsplus.com/tutorials/20-steps-to-a-flexible-and-secure-wordpress-installation--wp-13236" target="_blank" rel="noreferrer">20 Steps to a Flexible and Secure WordPress Installation</a> — WPTuts</li><li><a href="https://wordpress.org/plugins/" target="_blank" rel="noreferrer">WordPress Plugin Repository</a> — search for security plugins</li></ul><blockquote><p>This article is not a complete WordPress security guide, but a starting point to help you get set up safely.</p></blockquote>',9)])])}const f=r(i,[["render",o]]);export{h as __pageData,f as default};
